"""stage5_data.py (Ch 15-19 終極無矛盾版，附拉格朗日密技)"""

STAGE_5 = {'title': '第五階：機率密度初探、常微分方程與拉格朗日神級密技（第 15–19 堂）', 'theme': '二項分佈長條圖連續坍縮，一階常微分方程分離變數法，RC 暫態與簡諧振動，拉格朗日量神級密技出鞘', 'lessons': [{'id': 15, 'title': '從二項分佈長條圖到機率密度函數（高爾頓板、柱寬坍縮與連續微元初登場）', 'book_blueprint': '從古典離散硬幣試驗與高爾頓板（Galton Board）累積的直方圖切入；當試驗次數 n 趨於無窮且柱狀圖底寬 Delta x 趨於 dx 時，直方圖階梯平滑化為連續曲面；徹底破除高中生心魔——『連續型隨機變數在單一點的機率為何恆為零 P(X=c)=0？既然單點皆為零，區間機率為何能大於零？』；揭示機率密度函數（PDF）微元核心定義 dP = f(x) dx，即『函數高度不是機率，高度是機率密度；面積才是機率』；求機率本質即求黎曼和定積分；繪製標準鐘形曲線，並立下全書最大懸念——『為什麼曲線係數包含神秘常數 1/(sqrt(2pi) sigma)？』，將此數學債記於黑板，留待多變數微積分章節徹底清償。 本章承接定積分幾何概念，以直方圖極限破除單點機率為零心魔，並在黑板鄭重記下鐘形曲線 sqrt(2pi) 待償帳單，留待多變數微積分章節清償。', 'dojo_core': '黑板四分區實彈攻防：一區畫出高爾頓板下落鋼珠累積的二項分佈直方圖；二區推導單點柱寬 Delta x -> 0 時單點機率歸零的微元極限，揭示『高度不是機率，高度是密度』的核心本質；三區寫出定積分機率公式 P(a <= X <= b) = int_a^b f(x) dx；四區用紅粉筆大字寫下待付帳單：『int_{-inf}^inf e^{-x^2} dx = sqrt(pi) 到底怎麼算？單變數微積分無法攻破，多變數章節見！』', 'formulas': [{'id': 'Eq 15.1', 'name': '二項分佈離散機率質量公式', 'latex': 'P(X = k) = \\binom{n}{k} p^k (1-p)^{n-k}'}, {'id': 'Eq 15.2', 'name': '離散直方圖柱寬與微元步長式', 'latex': '\\Delta x = \\frac{x_{k+1}-x_k}{\\sigma}, \\quad \\lim_{n \\to \\infty} \\Delta x = \\mathrm{d}x'}, {'id': 'Eq 15.3', 'name': '機率密度函數微元定義式', 'latex': '\\mathrm{d}P = f(x)\\,\\mathrm{d}x \\implies f(x) = \\frac{\\mathrm{d}P}{\\mathrm{d}x}'}, {'id': 'Eq 15.4', 'name': '連續型區間機率黎曼和極限定積分式', 'latex': 'P(a \\le X \\le b) = \\lim_{\\Delta x \\to 0} \\sum f(x_k)\\Delta x = \\int_a^b f(x)\\,\\mathrm{d}x'}, {'id': 'Eq 15.5', 'name': '全域機率歸一化守恆式', 'latex': '\\int_{-\\infty}^{\\infty} f(x)\\,\\mathrm{d}x = 1'}, {'id': 'Eq 15.6', 'name': '連續隨機變數期望值一階矩積分式', 'latex': 'E[X] = \\int_{-\\infty}^{\\infty} x f(x)\\,\\mathrm{d}x'}, {'id': 'Eq 15.7', 'name': '鐘形曲線待清償懸念式', 'latex': 'f(x) = \\frac{1}{\\sqrt{2\\pi}\\sigma} e^{-\\frac{(x-\\mu)^2}{2\\sigma^2}} \\quad (\\sqrt{2\\pi}\\text{ 待多變數證明})'}], 'problems': {'worked_examples': [{'id': 'Ex 15.1', 'desc': '以均勻分佈 U[0, 10] 為例，證明單點 P(X=5) = 0，但區間 P(4.9 <= X <= 5.1) = 0.02；利用微元 dP = f(x) dx 闡釋『機率密度』與『物理線質量密度 dm = lambda dx』的一致性。'}, {'id': 'Ex 15.2', 'desc': '給定指數型機率密度 f(x) = lambda e^{-lambda x} (x >= 0)，利用定積分驗證全域機率歸一化 int_0^inf f(x) dx = 1，並無跳步計算其期望值 E[X] = 1/lambda。'}, {'id': 'Ex 15.3', 'desc': '高爾頓板模擬：設鋼珠經過 100 排釘子，每一步向右機率 p=0.5；畫出其二項分佈直方圖，並展示當縱軸縮放為機率密度時，頂部輪廓如何收斂為一條平滑鐘形曲線。'}], 'margin_inquiries': [{'id': 'Q1 15.1', 'desc': '若連續隨機變數在每一點的機率皆為 0，為何所有點的集合機率卻能等於 1？無窮個 0 相加為何不等於 0？'}, {'id': 'Q1 15.2', 'desc': '機率密度函數 f(x) 的值可以大於 1 嗎？若可以，舉出一個幾何範例並解釋為何不違背機率小於等於 1 的公理。'}, {'id': 'Q1 15.3', 'desc': '為什麼在單變數微積分中，我們找不到初等函數能直接作為 e^{-x^2} 的反導函數？這預示了什麼維度限制？'}], 'foundational_drills': [{'id': 'P1 15.1', 'desc': '設 f(x) = c(1 - x^2) 在 [-1, 1] 區間，區間外為 0；求使 f(x) 成為合法機率密度函數的常數 c。'}, {'id': 'P1 15.2', 'desc': '針對上述密度函數，手算累積機率 P(-0.5 <= X <= 0.5) 與期望值 E[X]。'}, {'id': 'P1 15.3', 'desc': '利用黎曼和定義，將極限 lim_{n -> inf} sum_{k=1}^n (1/n) f(k/n) 轉化為機率定積分式。'}, {'id': 'P1 15.4', 'desc': '若 X ~ U[a, b]，證明其方差 Var(X) = (b-a)^2 / 12，指出此公式與均勻細棒繞質心轉動慣量的微元關聯。'}], 'interdisciplinary_applications': [{'id': 'P5 15.1', 'desc': '【高中物理布朗運動】懸浮微粒的一維隨機位移服從微元擴散方程，推導經時間 t 後位移落在 [-sqrt{2Dt}, sqrt{2Dt}] 區間的定積分機率表達式。'}, {'id': 'P5 15.2', 'desc': '【高中化學反應速率】將活化分子比例視為能量超過閾值 E_a 的累積定積分，以簡易指數分佈 f(E) = (1/kT) e^{-E/kT} 導出阿瑞尼斯活化因子的微元面積本質。'}, {'id': 'P5 15.3', 'desc': '【高中生物遺傳性狀】多基因遺傳中身高分佈為數十對等位基因效應的疊加，用高爾頓板模型論證為何族群身高必然形成鐘形連續分佈。'}, {'id': 'P5 15.4', 'desc': '【信號測量誤差】儀器讀數誤差被建模為對稱連續分佈，證明任何奇函數誤差模型其期望誤差值必恆等於 0。'}], 'deepwater_challenges': [{'id': 'P9 15.1', 'desc': '柯西分佈 f(x) = (1/pi) * (1 / (1 + x^2)) 的全域積分為 1，但其期望值積分 int_{-inf}^inf x/(1+x^2) dx 卻因非絕對收斂而不存在，從幾何面積對稱性剖析此處微積分的主值悖論。'}, {'id': 'P9 15.2', 'desc': '設隨機變數 X 服從標準常態分佈形狀 f(x) = C e^{-x^2/2}；在不使用二重積分的情況下，利用階梯函數逼近法證明常數 C 必然介於 0.35 與 0.45 之間。'}], 'dojo_defense_tasks': [{'id': 'D1 15.1', 'desc': '學員在黑板寫下 P(X=3) = f(3)，導師當場叫停：『密度不是機率！如果 f(3)=2.5，難道機率能是 250%？立刻用微元 dP = f(x) dx 糾正，並給出物理維度解釋！』'}, {'id': 'D1 15.2', 'desc': '學員試圖計算常態分佈原函數，導師截停：『放棄無謂的單變數代換！在黑板寫下為何 e^{-x^2} 缺乏初等反導，並指出需要何種高維幾何武器。』'}, {'id': 'D1 15.3', 'desc': '黑板推導指數衰減分佈，學員在無窮積分上下限代入出現符號混亂，要求在 60 秒內以極限極限 lim_{R -> inf} 規範重構。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 15.1', 'desc': '未知破局：給定三角波機率密度 f(x) = 1 - |x| (|x| <= 1)，要求學生在不計算不定積分的前提下，純粹利用幾何面積求出中位數與四分位距。'}, {'id': 'U1 15.2', 'desc': '未知破局：若隨機變數 Y = X^2，其中 X ~ U[-1, 1]；學生必須利用累積機率分佈導出 Y 的機率密度函數 g(y)，體驗微積分換元在機率中的雅可比微商雛形。'}, {'id': 'U1 15.3', 'desc': '未知破局：給定一離散質點系向連續均勻棒過渡，要求在黑板左側列出離散期望值 sum x_i p_i，右側無跳步轉化為連續質心積分 (1/M) int x dm。'}], 'system_trivialization_arsenal': [{'id': 'K1 15.1', 'desc': '體制內考題秒殺：高中選修數學『求均勻分佈在 [2, 8] 之間大於 5 的機率』，體制內畫梯形，微積分選手直接寫下 int_5^8 (1/6) dx = 3/6 = 0.5 秒殺。'}, {'id': 'K1 15.2', 'desc': '體制內考題秒殺：化學大考活化能示意圖面積比較，微積分學員一眼識破為指數尾部積分 int_{E_a}^inf e^{-E/RT} dE = RT e^{-E_a/RT}，直接秒判溫度 T 升高時尾部面積的指數級暴增。'}, {'id': 'K1 15.3', 'desc': '體制內考題秒殺：統計考題『某常態分佈對稱軸為 10，則 P(X <= 10) 為何？』，微積分學員運用奇函數對稱積分為零特性，1 行寫出 0.5 結案。'}]}}, {'id': 16, 'title': '一階常微分方程分離變數法與反應動力學解析（牛頓冷卻與終端速度）', 'book_blueprint': '微分方程是自然界譜寫定律的通用語言。高中物理與化學充斥著『速率正比於差距』的動態過程：熱茶冷卻、雨滴下落、化學反應。本章正式開啟常微分方程（ODE）大門：標準一階微分方程 dy/dt = f(t, y)；當函數可分解為 g(t) h(y) 時，採用分離變數法 int (1/h(y)) dy = int g(t) dt 求解；實戰打擊三大高中經典模型：1. 牛頓冷卻定律 dT/dt = -k(T - T_env)，分離變數得 T(t) = T_env + (T_0 - T_env) e^{-kt}，破解降溫指數曲線；2. 空氣阻力下落模型 m dv/dt = mg - kv，導出速度函數 v(t) = (mg/k)(1 - e^{-kt/m})，令 t -> inf 自然浮現終端速度 v_term = mg/k；3. 化學一級反應動力學 d[A]/dt = -k[A]，積分收穫 [A](t) = [A]_0 e^{-kt}，與零級反應、二級反應在相圖上並列對決，完成動力學微積分第一性原理構建。', 'dojo_core': '黑板四分區實彈攻防：一區在黑板列出一階 ODE 分離變數的四部標準手術刀動線；二區現場推導空氣阻力下落，在黑板畫出 v-t 曲線如何從線性斜率 g 漸近彎折至水平線 mg/k；三區推導牛頓冷卻定律，對比不同介質散熱常數 k 的幾何衰減速度；四區以二級化學反應 1/[A] - 1/[A]_0 = kt 突襲學員，展示非指數型微分方程的特徵。', 'formulas': [{'id': 'Eq 16.1', 'name': '一階常微分方程分離變數標準式', 'latex': '\\frac{\\mathrm{d}y}{\\mathrm{d}t} = g(t)h(y) \\implies \\int \\frac{1}{h(y)}\\,\\mathrm{d}y = \\int g(t)\\,\\mathrm{d}t'}, {'id': 'Eq 16.2', 'name': '牛頓冷卻定律微分方程', 'latex': '\\frac{\\mathrm{d}T}{\\mathrm{d}t} = -k(T - T_{\\text{env}})'}, {'id': 'Eq 16.3', 'name': '牛頓冷卻溫度指數衰減解析解', 'latex': 'T(t) = T_{\\text{env}} + (T_0 - T_{\\text{env}}) e^{-kt}'}, {'id': 'Eq 16.4', 'name': '線性空氣阻力下落微分方程', 'latex': 'm\\frac{\\mathrm{d}v}{\\mathrm{d}t} = mg - kv'}, {'id': 'Eq 16.5', 'name': '終端速度與速度演化解析解', 'latex': 'v(t) = \\frac{mg}{k}\\left(1 - e^{-\\frac{k}{m}t}\\right) \\implies v_{\\text{term}} = \\lim_{t \\to \\infty} v(t) = \\frac{mg}{k}'}, {'id': 'Eq 16.6', 'name': '化學一級反應動力學方程與半衰期', 'latex': '\\frac{\\mathrm{d}[A]}{\\mathrm{d}t} = -k[A] \\implies [A](t) = [A]_0 e^{-kt}, \\quad t_{1/2} = \\frac{\\ln 2}{k}'}, {'id': 'Eq 16.7', 'name': '化學二級反應動力學解析式', 'latex': '\\frac{\\mathrm{d}[A]}{\\mathrm{d}t} = -k[A]^2 \\implies \\frac{1}{[A](t)} = \\frac{1}{[A]_0} + kt'}], 'problems': {'worked_examples': [{'id': 'Ex 16.1', 'desc': '一杯 90 度的咖啡置於 20 度的室溫環境中，5 分鐘後降溫至 60 度；利用牛頓冷卻定律分離變數求解散熱常數 k，並精確計算降溫至 30 度所需的總時間。'}, {'id': 'Ex 16.2', 'desc': '雨滴在重力與高速空氣二次方阻力 F_d = -c v^2 作用下下落，列出微分方程 m(dv/dt) = mg - c v^2，分離變數法利用部分分式求出速度解析解 v(t) = v_term tanh(gt / v_term)。'}, {'id': 'Ex 16.3', 'desc': '一階線性微分方程 dy/dt + P(t) y = Q(t)，構造積分因子 mu(t) = e^{int P dt}，無跳步推導出通解公式 y(t) = (1/mu) int mu Q dt + C/mu。'}], 'margin_inquiries': [{'id': 'Q1 16.1', 'desc': '在線性阻力下落模型中，速度在 t = 0 處的切線斜率（初始加速度）為何恰好是重力加速度 g？'}, {'id': 'Q1 16.2', 'desc': '為什麼化學一級反應的半衰期與反應物初始濃度完全無關，而二級反應的半衰期 t_{1/2} = 1/(k[A]_0) 卻反比於初始濃度？'}, {'id': 'Q1 16.3', 'desc': '積分常數 C 在物理世界中對應什麼？為什麼沒有初始條件（Cauchy 數據），微分方程就無法給出唯一的真實物理軌道？'}], 'foundational_drills': [{'id': 'P1 16.1', 'desc': '求解微分方程 dy/dx = 2x y，滿足初始條件 y(0) = 3。'}, {'id': 'P1 16.2', 'desc': '求解微分方程 dy/dt = -y^2，初始條件 y(0) = 1。'}, {'id': 'P1 16.3', 'desc': '某細菌培養物增長速率正比於當前數量 dy/dt = 0.05 y，求數量翻倍所需時間。'}, {'id': 'P1 16.4', 'desc': '物體自靜止下落受線性阻力，求下落距離隨時間變化的函數 x(t) = int v(t) dt。'}], 'interdisciplinary_applications': [{'id': 'P5 16.1', 'desc': '【法醫死亡時間推斷】死者體溫測量值隨時間衰減，結合現場環境溫度利用牛頓冷卻方程反推心跳停止的精確時刻。'}, {'id': 'P5 16.2', 'desc': '【跳傘運動員開傘動態】跳傘員自高空俯衝達到第一終端速度 50 m/s，開傘後阻力係數突變，求解降至第二終端速度 5 m/s 的過渡減速曲線與最大過載加速度。'}, {'id': 'P5 16.3', 'desc': '【藥物在人體代謝廓清率】靜脈注射藥物在血液中消除服從一級動力學 dC/dt = -k C，結合連續滴注速率 R_0，求解血液藥物濃度平穩態 C_ss = R_0 / k。'}, {'id': 'P5 16.4', 'desc': '【污染水體自淨自稀釋模型】湖泊體積 V，純淨水以流量 Q 流入並以同流量流出帶走污染物，求解污染物濃度隨時間指數稀釋方程。'}], 'deepwater_challenges': [{'id': 'P9 16.1', 'desc': '非線性白努利方程（Bernoulli ODE）：dy/dx + P(x) y = Q(x) y^n，引入變換 u = y^{1-n}，將其化為標準線性微分方程並給出通用積分公式。'}, {'id': 'P9 16.2', 'desc': '可變重力場大氣下落：考慮重力隨高度減小 g(z) = g_0 (R / (R+z))^2 且空氣密度隨高度指數衰減，列出隕石墜入大氣層的非線性二階 ODE 聯立方程。'}], 'dojo_defense_tasks': [{'id': 'D1 16.1', 'desc': '學員分離變數直接寫出 int dy/y = int dt，遺漏積分常數 C，導師截停：『常數呢？沒有常數你的初始條件往哪裡代？在黑板補上完整的通解與特解！』'}, {'id': 'D1 16.2', 'desc': '學員求終端速度令 a = 0，導師質問：『速度一直在變，加速度怎麼就變成 0 了？在黑板寫出速度極限 lim_{t -> inf} 的微積分過程！』'}, {'id': 'D1 16.3', 'desc': '學員在牛頓冷卻中寫出 dT/dt = -k T，忽視環境溫度，導師以冰水置於沸水環境為例，要求其寫出溫差驅動項。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 16.1', 'desc': '未知破局：設某容器排水孔出流速度服從托里切利定律 v = sqrt{2gh}，求水深 h(t) 隨時間變化的微分方程與排空總時間。'}, {'id': 'U1 16.2', 'desc': '未知破局：雪球在雪地上滾動，質量增長率正比於表面積 dm/dt = k S，求解雪球半徑隨時間的增長規律。'}, {'id': 'U1 16.3', 'desc': '未知破局：求解微分方程 (x + 1) dy/dx = y + 1，滿足 y(0) = 1。'}], 'system_trivialization_arsenal': [{'id': 'K1 16.1', 'desc': '體制內考題秒殺：高中大考阻力下落題，體制內學生猜測圖像，微積分選手看 v(t) = v_term(1 - e^{-t/tau}) 5 秒勾出正確漸近曲線。'}, {'id': 'K1 16.2', 'desc': '體制內考題秒殺：化學反應級數判斷，微積分選手觀察半衰期是否恆定，1 秒秒殺一級還是二級反應。'}, {'id': 'K1 16.3', 'desc': '體制內考題秒殺：降溫問題估算，微積分學員利用 Delta T 呈等比數列衰減，10 秒心算答案。'}]}}, {'id': 17, 'title': '變質量運動學微分方程與連續介質流體光壓（火箭推進對數解與雷射光壓）', 'book_blueprint': '從牛頓第二定律的原始形態 F = dp/dt 出發，當系統質量隨時間連續變化時，微分連鎖律展開為 F = m (dv/dt) + v (dm/dt)；以此微商算子直接破解高中物理最大盲區——『連續流體衝擊力』與『齊奧爾科夫斯基火箭方程式』。水槍衝擊牆面：流體質量微元 dm = rho A v dt，單位時間動量改变量 dp/dt = rho A v^2，瞬間秒殺高中浮誇的離散撞擊模型；火箭推進：排出氣體質量微元 dm < 0，相對噴氣速度 u，分離變數法積分 m dv = -u dm，導出 Delta v = u ln(m_0/m)；進一步推廣至連續介質光子流，單個光子動量 p = E/c，雷射照射吸收表面光壓 P = I/c，全反射表面光壓 P = 2I/c，徹底貫通宏觀流體力學與近代光壓物理。', 'dojo_core': '黑板四分區實彈攻防：一區以微元圖展示時間 dt 內流入控制體的質量 dm = rho A v dt；二區在黑板推導火箭變質量微分方程，分離變數法得出對數關係式；三區列出光子束動量流率，對比完全吸收與全反射的動量反彈微元；四區當面電擊『用 F = ma 算流水衝力』的學員，演示流體動量流率算子的不可替代性。', 'formulas': [{'id': 'Eq 17.1', 'name': '連續介質質量流率微元式', 'latex': '\\frac{\\mathrm{d}m}{\\mathrm{d}t} = \\rho A v'}, {'id': 'Eq 17.2', 'name': '流體定常衝擊力動量流率式', 'latex': 'F = \\frac{\\mathrm{d}p}{\\mathrm{d}t} = v \\frac{\\mathrm{d}m}{\\mathrm{d}t} = \\rho A v^2'}, {'id': 'Eq 17.3', 'name': '變質量系統動量微分方程', 'latex': 'm\\,\\mathrm{d}v = -u\\,\\mathrm{d}m \\quad (u \\text{ 為相對噴氣速度})'}, {'id': 'Eq 17.4', 'name': '齊奧爾科夫斯基火箭公式', 'latex': '\\Delta v = u \\ln\\left(\\frac{m_0}{m}\\right)'}, {'id': 'Eq 17.5', 'name': '光子流動量能量關係式', 'latex': 'p = \\frac{E}{c} \\implies \\frac{\\mathrm{d}p}{\\mathrm{d}t} = \\frac{1}{c}\\frac{\\mathrm{d}E}{\\mathrm{d}t} = \\frac{P_{\\text{power}}}{c}'}, {'id': 'Eq 17.6', 'name': '完全吸收表面輻射光壓式', 'latex': 'P_{\\text{abs}} = \\frac{F}{A} = \\frac{I}{c}'}, {'id': 'Eq 17.7', 'name': '完全反射表面輻射光壓式', 'latex': 'P_{\\text{ref}} = \\frac{2I}{c}'}], 'problems': {'worked_examples': [{'id': 'Ex 17.1', 'desc': '一根均勻柔軟鏈條長度為 L、質量為 M，懸掛於天花板上；將其剪斷落至地面秤盤上，利用動量流率 F = v(dm/dt) + 重力，證明當落下長度為 x 時秤盤讀數恰為 3 * (M/L) g x。'}, {'id': 'Ex 17.2', 'desc': '推導垂直向上發射的火箭在均勻重力場 g 中的速度公式：m(dv/dt) = -u(dm/dt) - mg，分離變數法嚴格求出 v(t) = -gt + u ln(m_0 / (m_0 - alpha t))。'}, {'id': 'Ex 17.3', 'desc': '太陽常數在地球表面處為 I = 1361 W/m^2，計算面積為 1000 m^2 的理想全反射太陽帆在近地軌道所受到的微元光壓總推力。'}], 'margin_inquiries': [{'id': 'Q1 17.1', 'desc': '鏈條下落著地時，機械能是否守恆？秤盤讀數中的 3 倍係數，其中 2 倍來自流體衝力，1 倍來自靜重力，這是否意味著能量在碰撞中耗散？'}, {'id': 'Q1 17.2', 'desc': '火箭公式中為什麼出現自然對數 ln？如果質量消耗是線性的，為何速度不是線性的？'}, {'id': 'Q1 17.3', 'desc': '全反射表面的光壓恰好是全吸收表面的 2 倍，這與彈性碰撞的速度反彈有何微積分對偶關係？'}], 'foundational_drills': [{'id': 'P1 17.1', 'desc': '水射流直徑 d = 2 cm，速度 v = 10 m/s 垂直衝擊靜止牆面，求水流對牆面的衝力（水密度 1000 kg/m^3）。'}, {'id': 'P1 17.2', 'desc': '若上述水流衝擊以速度 u = 3 m/s 遠離噴嘴的葉片，寫出動量流率修正公式並求出衝力。'}, {'id': 'P1 17.3', 'desc': '火箭有效載荷質量為 m_p，結構質量比為 0.1，噴氣速度 3000 m/s，求使火箭達到第一宇宙速度 7.9 km/s 所需的質量比。'}, {'id': 'P1 17.4', 'desc': '功率為 10 kW 的工業雷射束垂直照射完全吸收靶，求雷射光子流對靶施加的微小推力。'}], 'interdisciplinary_applications': [{'id': 'P5 17.1', 'desc': '【太陽風與彗星尾巴】太陽輻射光壓與萬有引力對微粒的半徑依賴性：引力正比於 r^3，光壓正比於 r^2，推導塵埃顆粒被吹飛形成彗尾的臨界微粒半徑。'}, {'id': 'P5 17.2', 'desc': '【傳送帶傳送砂石功率】砂石以流量 dm/dt = 100 kg/s 落入速度 v = 2 m/s 的水平傳送帶，求傳送帶驅動電機必須提供的額外功率 P = (dm/dt) v^2，解釋為何其中一半化為摩擦熱。'}, {'id': 'P5 17.3', 'desc': '【直升機懸停微積分】直升機旋翼半徑 R，在空氣中向下推動空氣柱產生懸停升力，利用動量流率 F = rho A v^2 = M g 導出懸停所需的最小引擎誘導功率。'}, {'id': 'P5 17.4', 'desc': '【光鑷微粒操控】利用強聚焦高斯雷射束照射折射率大於介質的微米級小球，利用光子動量折射微元分析光鑷梯度力的幾何來源。'}], 'deepwater_challenges': [{'id': 'P9 17.1', 'desc': '相對論變質量火箭：若排氣速度達到光速 fraction c，利用相對論動量方程推導相對論齊奧爾科夫斯基方程式。'}, {'id': 'P9 17.2', 'desc': '雨滴在重力場中下落並沿途凝聚水汽，質量增加率 dm/dt = k v，列出一階非線性 ODE 並求解雨滴的終端加速度與速度。'}], 'dojo_defense_tasks': [{'id': 'D1 17.1', 'desc': '學員計算水流衝力寫出 F = m a，導師截停：『水流速度恆定，加速度 a=0，難道衝力是 0 嗎？立刻在黑板寫出連續介質動量流率形式！』'}, {'id': 'D1 17.2', 'desc': '學員推導傳送帶功率寫下 P = F v = (dm/dt v) v = (dm/dt) v^2，但動能增加率卻是 1/2 (dm/dt) v^2，導師逼問：『消失的 1/2 去了哪裡？』'}, {'id': 'D1 17.3', 'desc': '學員宣稱『光沒有質量所以不可能有壓力』，導師在黑板寫下 p = E/c，要求其在 60 秒內由電磁能量流密度導出光壓公式。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 17.1', 'desc': '未知破局：設一條懸掛的均勻重繩被提著上端向上勻速提升，當提升速度為 v 時，推導手部施加的拉力 F(t) 包含的動量微元項。'}, {'id': 'U1 17.2', 'desc': '未知破局：氣球破孔漏氣噴氣推進，假設漏氣質量流率隨內部氣壓呈微積分衰減，求解氣球在空中的速度-時間解析曲線。'}, {'id': 'U1 17.3', 'desc': '未知破局：宇宙塵埃雲阻力模型，飛船以初始速度 v_0 穿過密度為 rho 的塵埃雲，塵埃完全附著在飛船表面，求解飛船速度隨位移 x 的衰減函數。'}], 'system_trivialization_arsenal': [{'id': 'K1 17.1', 'desc': '體制內考題秒殺：高中物理『水龍頭噴水衝擊磅秤讀數』，體制內學生糾結微小時間 dt，微積分學員 1 秒寫出 F = rho A v^2 秒殺。'}, {'id': 'K1 17.2', 'desc': '體制內考題秒殺：砂石落入車斗模型，微積分學員直接引用動量定理 F = v (dm/dt) 瞬間鎖定牽引力。'}, {'id': 'K1 17.3', 'desc': '體制內考題秒殺：火箭分級推進速度估算，微積分選手直接寫下 Delta v = u ln(m_1/m_2) 3 行得出體制內大題最終解。'}]}}, {'id': 18, 'title': 'RC、RL 暫態電路一階線性微分方程與指數衰減（50% 能量佯謬微積分閉環）', 'book_blueprint': '高中選修物理電學板塊最具思辨性的硬核專題——RC 與 RL 暫態電路。課本只給出充電公式 q(t) = C E (1 - e^{-t/RC}) 與放電公式，卻從不給出克希荷夫電壓定律（KVL）與微積分的結合推導。本章以電路微積分微分方程開篇：充電迴路 E - i R - q/C = 0，代入電流定義 i = dq/dt，誕生一階線性非齊次 ODE：R(dq/dt) + q/C = E；分離變數法分離電荷與時間：dq / (C E - q) = dt / (RC)，積分嚴格導出電荷指數增長 q(t) = C E (1 - e^{-t/tau})，其中時間常數 tau = RC 決定充放電快慢；同理推導 RL 迴路自感漸近電流 i(t) = (E/R)(1 - e^{-Rt/L})；最後，以微積分審判高中物理最震撼的『50% 能量佯謬』：電池輸出總能量 W_bat = int E i dt = C E^2，而電容器終態儲存能量僅為 1/2 C E^2，定積分手算電阻熱損耗 W_R = int_0^inf i^2 R dt = 1/2 C E^2，證明無論電阻 R 多微小，恰好一半的能量必然耗散為焦耳熱，徹底震撼學生的物理認知！', 'dojo_core': '黑板四分區實彈攻防：一區在黑板畫出 RC 充電迴路圖，列出克希荷夫電壓方程並化為標準 ODE；二區無跳步推導分離變數法，在黑板畫出電荷 q(t) 與電流 i(t) 的對稱反向指數曲線；三區推導 RL 迴路的時間常數 tau = L/R；四區對決 50% 能量佯謬，三條定積分線路現場算平帳單（電池功 = 電容能 + 電阻熱），全場學員震撼受教。', 'formulas': [{'id': 'Eq 18.1', 'name': 'RC 充電迴路克希荷夫微分方程', 'latex': 'R\\frac{\\mathrm{d}q}{\\mathrm{d}t} + \\frac{q}{C} = \\mathcal{E}'}, {'id': 'Eq 18.2', 'name': '電容充電電荷與電流指數解析式', 'latex': 'q(t) = C\\mathcal{E}\\left(1 - e^{-\\frac{t}{RC}}\\right), \\quad i(t) = \\frac{\\mathrm{d}q}{\\mathrm{d}t} = \\frac{\\mathcal{E}}{R} e^{-\\frac{t}{RC}}'}, {'id': 'Eq 18.3', 'name': '電容放電指數衰減公式', 'latex': 'q(t) = Q_0 e^{-\\frac{t}{RC}}, \\quad i(t) = -\\frac{Q_0}{RC} e^{-\\frac{t}{RC}}'}, {'id': 'Eq 18.4', 'name': 'RC 與 RL 電路時間常數定義', 'latex': '\\tau_{RC} = RC, \\quad \\tau_{RL} = \\frac{L}{R}'}, {'id': 'Eq 18.5', 'name': 'RL 電路通電電流增長微分方程與解', 'latex': 'L\\frac{\\mathrm{d}i}{\\mathrm{d}t} + i R = \\mathcal{E} \\implies i(t) = \\frac{\\mathcal{E}}{R}\\left(1 - e^{-\\frac{R}{L}t}\\right)'}, {'id': 'Eq 18.6', 'name': '電源充電輸出總能量定積分式', 'latex': 'W_{\\text{bat}} = \\int_0^\\infty \\mathcal{E} i(t)\\,\\mathrm{d}t = \\mathcal{E} \\int_0^\\infty \\mathrm{d}q = C\\mathcal{E}^2'}, {'id': 'Eq 18.7', 'name': '電阻焦耳熱定積分與 50% 能量佯謬閉環', 'latex': 'W_R = \\int_0^\\infty i(t)^2 R\\,\\mathrm{d}t = \\int_0^\\infty \\frac{\\mathcal{E}^2}{R} e^{-\\frac{2t}{RC}}\\,\\mathrm{d}t = \\frac{1}{2}C\\mathcal{E}^2 = W_{\\text{bat}} - E_C'}], 'problems': {'worked_examples': [{'id': 'Ex 18.1', 'desc': '在 RC 充電電路中，無跳步推導電阻瞬時消耗功率 P_R(t) = i^2 R，求使電阻瞬時功率達到最大的時間點 t_max，並證明該最大功率為 E^2 / (4R)。'}, {'id': 'Ex 18.2', 'desc': '一電感為 L、電阻為 R 的線圈連接至直流電源 E；當電流達到穩定態 E/R 後瞬間短路電源，利用定積分計算磁場能量釋放過程中的總焦耳熱，驗證其等於 1/2 L (E/R)^2。'}, {'id': 'Ex 18.3', 'desc': '雙電容電荷重新分配：一電容 C_1 帶電 Q_0，另一電容 C_2 未充電，兩者通過電阻 R 閉合；列出微分方程求解電流 i(t)，並用微積分證明無論 R 多大，損失的靜電能恆等於 1/2 [C_1 C_2 / (C_1 + C_2)] (Q_0/C_1)^2。'}], 'margin_inquiries': [{'id': 'Q1 18.1', 'desc': '在時間常數 t = tau = RC 瞬間，電容器充滿了百分之多少的電荷？（手算 1 - 1/e approx 63.2%）'}, {'id': 'Q1 18.2', 'desc': '如果電路中的電阻 R -> 0（超導電路），50% 的能量損失依然存在嗎？微積分與物理極限在這裡揭示了什麼電磁輻射本質？'}, {'id': 'Q1 18.3', 'desc': '為什麼電感在接通瞬間相當於『斷路』（電流為 0），而電容在接通瞬間相當於『短路』（電壓為 0）？從微積分導數 d/dt 的角度解釋。'}], 'foundational_drills': [{'id': 'P1 18.1', 'desc': '電容 C = 10 muF 與電阻 R = 100 kOmega 串聯，計算其時間常數 tau。'}, {'id': 'P1 18.2', 'desc': '若電源電壓為 10V，求上述電路接通後 2 秒時電容器兩端的電壓。'}, {'id': 'P1 18.3', 'desc': '求電容充電至 99% 所需的時間是時間常數 tau 的多少倍？（手算 ln 100）'}, {'id': 'P1 18.4', 'desc': 'RL 電路中 L = 2H, R = 10 Omega，求電流上升到最大值一半所需的時間。'}], 'interdisciplinary_applications': [{'id': 'P5 18.1', 'desc': '【神經元軸突信號傳導】神經元膜電位被建模為 RC 漏電積分器（Leaky Integrate-and-Fire），突觸電流輸入時膜電位按 V(t) = R I (1 - e^{-t/RC}) 充能，求解達到觸發閾值時的動作電位點火延遲。'}, {'id': 'P5 18.2', 'desc': '【心臟起搏器定時電路】利用 RC 電路充放電週期控制電脈衝釋放頻率，求維持每分鐘 72 次心跳所需調節的電阻阻值。'}, {'id': 'P5 18.3', 'desc': '【相機閃光燈高壓充能】利用升壓變壓器與 RC 電路在 5 秒內將 330 muF 電容充至 300V，計算充電平均功率與閃光瞬間在 1 ms 內的峰值放電功率。'}, {'id': 'P5 18.4', 'desc': '【電源濾波低通濾波器】RC 電路對高頻交流信號呈現衰減，利用微商推導截止頻率 f_c = 1 / (2 pi RC)。'}], 'deepwater_challenges': [{'id': 'P9 18.1', 'desc': 'RLC 串聯二階暫態電路：L (d^2 q / dt^2) + R (dq/dt) + q/C = E，列出特徵方程並求解欠阻尼（Oscillatory）、臨界阻尼（Critically Damped）、過阻尼（Overdamped）三種情形的臨界電阻 R_c = 2 sqrt{L/C}。'}, {'id': 'P9 18.2', 'desc': '超導雙電容輻射損耗：在無電阻超導電路中，利用麥克斯韋電磁場方程推導電荷重新分配時損失的能量 1/2 C V^2 如何完全以電磁波輻射（坡印廷向量能流積分）散逸至無窮遠。'}], 'dojo_defense_tasks': [{'id': 'D1 18.1', 'desc': '學員推導電容充電功寫出 W_bat = 1/2 C E^2，導師截停：『那是電容儲存的能量！電池做了多少功？在黑板寫出 int E i dt 手算給全班看！』'}, {'id': 'D1 18.2', 'desc': '學員稱『只要電阻足夠小，電阻發熱就可以忽略』，導師在黑板手算定積分 W_R = int i^2 R dt，指出 R 在分母與分子相消，結果恆為 1/2 C E^2。'}, {'id': 'D1 18.3', 'desc': '學員在 RL 電路中將時間常數寫成 tau = R L，導師要求用維度分析與微分方程量綱檢查當場修正。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 18.1', 'desc': '未知破局：設電源電壓隨時間線性上升 E(t) = alpha t，求解 RC 電路中的電荷 q(t) 響應曲線。'}, {'id': 'U1 18.2', 'desc': '未知破局：電容器漏電模型，極板間存在漏電阻 R_leak，求解斷開電源後電壓的自放電指數曲線。'}, {'id': 'U1 18.3', 'desc': '未知破局：求階躍電壓激勵下，RL 電路電感兩端感應電動勢 V_L(t) 的時間波形。'}], 'system_trivialization_arsenal': [{'id': 'K1 18.1', 'desc': '體制內考題秒殺：高中大考電容充電圖像題，微積分學員看 q(t) 指數向上凸、i(t) 指數向下凹，2 秒選中唯一正確圖案。'}, {'id': 'K1 18.2', 'desc': '體制內考題秒殺：電路斷開瞬間反電動勢峰值，微積分選手看 L di/dt 斷開瞬間 dt -> 0 產生高壓電弧，瞬間定性秒答。'}, {'id': 'K1 18.3', 'desc': '體制內考題秒殺：能量損失題，微積分選手直接寫下 Delta E = 1/2 C V^2 1 秒拿滿分。'}]}}, {'id': 19, 'title': '二階常係數齊次線性 ODE 與簡諧運動（淘汰參考圓，附道場神級密技：拉格朗日量 L = T - V）', 'book_blueprint': "高中物理講簡諧運動（SHM），所有參考書和課本都在畫一個莫名其妙的『參考圓投影』。學生被迫在圓周運動和水平投影之間反覆折磨，卻不知這純粹是微積分未引進前的歷史妥協！本章以微積分第一性原理徹底淘汰參考圓：牛頓第二定律 F = -k x = m (d^2 x / dt^2)，誕生二階常係數齊次線性微分方程 d^2 x / dt^2 + omega^2 x = 0（其中 omega = sqrt{k/m}）；特徵方程 r^2 + omega^2 = 0 誕生虛數根 r = +- i omega；由歐拉公式導出實數通解 x(t) = c_1 cos(omega t) + c_2 sin(omega t) = A cos(omega t + phi)；振幅 A 與初相位 phi 純粹由初始條件（x_0, v_0）自然代數解出，根本不需要畫任何圓！進一步求解單擺非線性方程 d^2 theta / dt^2 + (g/L) sin theta = 0，利用小角度泰勒展開 sin theta approx theta 導出週期 T = 2 pi sqrt{L/g}；最後推導阻尼振盪方程 m x'' + b x' + k x = 0，展現微積分在動力學世界的全域統御力。 【道場神級密技特典：拉格朗日量】在深水挑戰與道場未知破局環節，正式解鎖分析力學黑魔法 L = T - V 與尤拉-拉格朗日方程 d/dt(partial L / partial q_dot) - partial L / partial q = 0；免畫任何受力圖、免分解約束力（正向力、繩張力自動消除），3 行自動生成複雜約束系統的二階運動微分方程（小車單擺、雙彈簧振子黑板秒殺），為資優生提供競賽與大考的終極檢驗底牌！", 'dojo_core': '黑板四分區實彈攻防：一區在黑板大字寫下宣言：『今天在黑板上，我們正式為參考圓舉行葬禮！』；二區無跳步推導二階常係數 ODE 特徵方程與歐拉解，展示 A 與 phi 如何由初值條件唯一決定；三區推導單擺小角度泰勒近似，展示大角度下週期拉長的微擾修正；四區對決阻尼振盪的三種判別式，徹底橫掃高難度競賽題。 【道場黑板黑魔法對決】黑板左側展示體制內牛頓力學寫滿兩黑板的受力分解與慣性力補償；黑板右側亮出拉格朗日量 L = T - V，3 步無腦套入尤拉-拉格朗日方程，3 行自動吐出二階運動微分方程，徹底震撼全場資優生！', 'formulas': [{'id': 'Eq 19.1', 'name': '簡諧運動二階標準微分方程', 'latex': '\\frac{\\mathrm{d}^2 x}{\\mathrm{d}t^2} + \\omega^2 x = 0 \\quad \\left(\\omega = \\sqrt{\\frac{k}{m}}\\right)'}, {'id': 'Eq 19.2', 'name': '特徵方程與歐拉複數根展開式', 'latex': 'r^2 + \\omega^2 = 0 \\implies r = \\pm i\\omega \\implies x(t) = c_1 e^{i\\omega t} + c_2 e^{-i\\omega t}'}, {'id': 'Eq 19.3', 'name': '簡諧運動實數通用解析解', 'latex': 'x(t) = A \\cos(\\omega t + \\phi) = x_0 \\cos(\\omega t) + \\frac{v_0}{\\omega} \\sin(\\omega t)'}, {'id': 'Eq 19.4', 'name': '簡諧運動振幅與初相一代數確定式', 'latex': 'A = \\sqrt{x_0^2 + \\left(\\frac{v_0}{\\omega}\\right)^2}, \\quad \\tan\\phi = -\\frac{v_0}{\\omega x_0}'}, {'id': 'Eq 19.5', 'name': '單擺非線性微分方程與小角近似', 'latex': '\\frac{\\mathrm{d}^2\\theta}{\\mathrm{d}t^2} + \\frac{g}{L}\\sin\\theta = 0 \\xrightarrow{\\sin\\theta \\approx \\theta} \\frac{\\mathrm{d}^2\\theta}{\\mathrm{d}t^2} + \\frac{g}{L}\\theta = 0 \\implies T = 2\\pi\\sqrt{\\frac{L}{g}}'}, {'id': 'Eq 19.6', 'name': '簡諧運動速度與加速度導函數式', 'latex': 'v(t) = \\frac{\\mathrm{d}x}{\\mathrm{d}t} = -A\\omega\\sin(\\omega t+\\phi), \\quad a(t) = \\frac{\\mathrm{d}^2 x}{\\mathrm{d}t^2} = -A\\omega^2\\cos(\\omega t+\\phi) = -\\omega^2 x'}, {'id': 'Eq 19.7', 'name': '阻尼振動特徵微分方程', 'latex': "m\\frac{\\mathrm{d}^2 x}{\\mathrm{d}t^2} + b\\frac{\\mathrm{d}x}{\\mathrm{d}t} + k x = 0 \\implies x(t) = A e^{-\\gamma t} \\cos(\\omega' t + \\phi) \\quad \\left(\\gamma = \\frac{b}{2m}\\right)"}], 'problems': {'worked_examples': [{'id': 'Ex 19.1', 'desc': '質量為 m 的彈簧振子，初始位置 x(0) = x_0，初始速度 v(0) = v_0；不借助參考圓，純粹利用特徵解待定係數法無跳步求出 A 與 phi，並手算驗證機械能守恆 1/2 k A^2 = 1/2 k x_0^2 + 1/2 m v_0^2。'}, {'id': 'Ex 19.2', 'desc': '浮筒垂直振盪：質量為 M、橫截面積為 A 的圓柱形浮筒浮在密度為 rho 的液體中，微小下壓 x 後釋放；列出牛頓第二定律二階 ODE，求振盪固有頻率 omega = sqrt{rho A g / M} 與週期。'}, {'id': 'Ex 19.3', 'desc': "受迫振盪與共振：m x'' + k x = F_0 cos(omega_f t)，利用待定特解法求出穩態振幅 A(omega_f) = (F_0/m) / |omega_0^2 - omega_f^2|，分析驅動頻率接近固有頻率時的共振發散現象。"}], 'margin_inquiries': [{'id': 'Q1 19.1', 'desc': '為什麼簡諧運動的速度超前位移 pi/2（90度），而加速度超前位移 pi（180度）？從對正弦函數求導的角度解釋。'}, {'id': 'Q1 19.2', 'desc': '如果彈簧振子受到乾摩擦力（Coulomb Friction）而不是黏性阻力，微分方程的振幅衰減會是指數衰減還是等差線性衰減？'}, {'id': 'Q1 19.3', 'desc': '參考圓在歷史上是誰發明的？為什麼在沒有微積分教學的高中階段，參考圓會成為一種權宜之計？'}], 'foundational_drills': [{'id': 'P1 19.1', 'desc': "求解二階微分方程 y'' + 9y = 0，滿足 y(0) = 2, y'(0) = 0。"}, {'id': 'P1 19.2', 'desc': '求質點簡諧運動 x(t) = 5 cos(2t - pi/3) 的振幅、角頻率、頻率、週期與初相位。'}, {'id': 'P1 19.3', 'desc': '長度為 1 米的單擺在月球表面（g = 1.62 m/s^2）的微小擺動週期是多少？'}, {'id': 'P1 19.4', 'desc': '驗證 x(t) = e^{-t} (cos 2t + sin 2t) 是某二階阻尼振盪微分方程的解，求該方程的特徵根。'}], 'interdisciplinary_applications': [{'id': 'P5 19.1', 'desc': '【摩天大樓調諧質量阻尼器 TMD】台北 101 大樓風阻尼球被建模為巨型單擺，分析阻尼球與大樓主體雙自由度耦合二階 ODE 的共振消能機制。'}, {'id': 'P5 19.2', 'desc': '【分子雙原子分子震動光譜】HCl 分子共價鍵被近似為微觀量子彈簧，由紅外光譜實測振動頻率反推化學鍵彈簧剛度係數 k。'}, {'id': 'P5 19.3', 'desc': '【汽車懸吊系統避震器】汽車過減速帶模型，由車身質量與彈簧阻尼構成二階方程，求最佳臨界阻尼比 zeta = b / (2 sqrt{k m}) = 0.7 避免車身顛簸晃動。'}, {'id': 'P5 19.4', 'desc': '【LC 迴路電磁振盪對偶】證明 LC 迴路電荷方程 L(d^2 q / dt^2) + q/C = 0 與彈簧振子方程完全同構，列出所有物理量的對偶表（L 對應 m，1/C 對應 k，q 對應 x，i 對應 v）。'}], 'deepwater_challenges': [{'id': 'P9 19.1', 'desc': '【拉格朗日量神級密技實彈】光滑水平地面上有一質量為 M 的滑塊，其上懸掛一長度為 L、質量為 m 的單擺；純粹利用廣義坐標 (x, theta) 寫出系統動能 T 與位能 V，構造拉格朗日量 L = T - V；不畫任何受力圖，直接套用尤拉-拉格朗日方程式，3 行嚴格推導出小車與單擺的雙自由度耦合二階運動微分方程組！'}, {'id': 'P9 19.2', 'desc': '相空間相軌跡（Phase Portrait）：在 (x, v) 平面上畫出簡諧運動的閉合橢圓軌跡；證明對於阻尼振盪，相軌跡演化為一條螺旋向內卷吸至原點的吸引子螺旋線。'}], 'dojo_defense_tasks': [{'id': 'D1 19.1', 'desc': '學員試圖在黑板畫參考圓算相位，導師截停：『擦掉這個圓！寫出特徵方程，用初值條件直接解出 A 和 phi，展現微積分的尊嚴！』'}, {'id': 'D1 19.2', 'desc': '學員稱『單擺週期恆與振幅無關』，導師在黑板寫出 theta = 90 度，要求學員指證小角度近似 sin theta approx theta 的失效邊界。'}, {'id': 'D1 19.3', 'desc': '學員推導加速度寫出 a = omega^2 x，遺漏負號，導師逼問：『加速度方向與位移同向？那物體豈不是無限加速飛出宇宙了？』'}], 'unseen_sandbox_scenarios': [{'id': 'U1 19.1', 'desc': '未知破局：設 U 形管水銀柱長度為 L，將水銀柱輕微壓下一段距離 x 後釋放，求水銀柱微小往復振盪的週期。'}, {'id': 'U1 19.2', 'desc': '未知破局：兩根同軸旋轉的水平滾筒以角速度 omega 反向旋轉，上方放置一根均勻鋼棒，求鋼棒在動摩擦力作用下的簡諧運動週期。'}, {'id': 'U1 19.3', 'desc': "未知破局：求微分方程 y'' - 4y' + 4y = 0 的通解（特徵根重根情形）。"}], 'system_trivialization_arsenal': [{'id': 'K1 19.1', 'desc': '體制內競賽壓軸題秒殺：複雜雙約束質點振動問題，體制內受力分析耗時 25 分鐘且極易漏正負號，微積分選手使用拉格朗日量 L = T - V 3 行自動輸出運動微分方程，30 秒鎖定固有頻率！'}, {'id': 'K1 19.2', 'desc': '體制內考題秒殺：單擺週期變化題（如帶電單擺加電場），微積分學員求出等效 g_eff，1 行寫出新週期。'}, {'id': 'K1 19.3', 'desc': '體制內考題秒殺：彈簧振子動能與位能相等位置，微積分選手看 cos^2(omega t) = sin^2(omega t) 瞬間得出 x = A / sqrt{2}。'}]}}]}
